this is our old nginx log summary script, someone wrote it ages ago. still works on 3.12 but it's ugly. can you modernize it? the output format has to stay exactly the same, a cron job parses it

```python
#!/usr/bin/env python
# -*- coding: utf-8 -*-
import os, sys, re
import string

LOG_DIR = '/var/log/nginx'

def parse_line(line):
    m = re.match(r'(\S+) \S+ \S+ \[(.*?)\] "(\S+) (\S+) \S+" (\d{3}) (\d+|-)', line)
    if m == None:
        return None
    d = {}
    d['ip'] = m.group(1)
    d['time'] = m.group(2)
    d['method'] = m.group(3)
    d['path'] = m.group(4)
    d['status'] = int(m.group(5))
    if m.group(6) == '-':
        d['bytes'] = 0
    else:
        d['bytes'] = int(m.group(6))
    return d

def main():
    if len(sys.argv) > 1:
        n = int(sys.argv[1])
    else:
        n = 20
    files = os.listdir(LOG_DIR)
    stats = {}
    total_bytes = 0
    errors = 0
    for f in files:
        if not f.startswith('access.log'):
            continue
        if f.endswith('.gz'):
            continue
        fh = open(os.path.join(LOG_DIR, f))
        for line in fh.readlines():
            rec = parse_line(line)
            if rec == None:
                continue
            if rec['path'] in stats.keys():
                stats[rec['path']] = stats[rec['path']] + 1
            else:
                stats[rec['path']] = 1
            total_bytes = total_bytes + rec['bytes']
            if rec['status'] >= 500:
                errors = errors + 1
        fh.close()
    items = stats.items()
    items = sorted(items, key=lambda x: x[1], reverse=True)
    for path, count in items[:n]:
        print('%-50s %d' % (path, count))
    print('total bytes: %s' % total_bytes)
    print('5xx: ' + str(errors))

if __name__ == '__main__':
    main()
```

