The function already has natural seams (your comments mark most of them), so the split is mostly mechanical. The top-level function now reads like the business process, and each step can be tested with a fake `db`:

```python
from dataclasses import dataclass

TAX_RATES = {"DE": 0.19, "AT": 0.20, "FR": 0.20}
SHIPPING_FEE = 4.90
FREE_SHIPPING_FROM = 50


@dataclass(frozen=True)
class Totals:
    subtotal: float
    discount: float
    tax: float
    shipping: float
    total: float


def process_order(order_data, db, mailer):
    validate_order(order_data)
    customer = load_customer(db, order_data["customer_id"])
    items = order_data["items"]

    subtotal = price_items(db, items)
    discount = coupon_discount(db, order_data.get("coupon"), subtotal)
    totals = compute_totals(subtotal, discount, customer["country"])

    reserve_stock(db, items)
    order_id = db.insert_order(
        customer["id"], items,
        totals.subtotal, totals.discount, totals.tax, totals.shipping, totals.total,
    )
    mailer.send(customer["email"], "Order confirmation",
                confirmation_body(customer, order_id, items, totals.total))
    return order_id


def validate_order(order_data):
    if "items" not in order_data or len(order_data["items"]) == 0:
        raise ValueError("order has no items")
    if "customer_id" not in order_data:
        raise ValueError("missing customer")


def load_customer(db, customer_id):
    customer = db.get_customer(customer_id)
    if customer is None:
        raise ValueError("unknown customer")
    return customer


def price_items(db, items):
    """Check that every SKU exists and is in stock, return the subtotal."""
    subtotal = 0
    for item in items:
        product = db.get_product(item["sku"])
        if product is None:
            raise ValueError(f"unknown sku {item['sku']}")
        if product["stock"] < item["qty"]:
            raise ValueError(f"not enough stock for {item['sku']}")
        subtotal += product["price"] * item["qty"]
    return subtotal


def coupon_discount(db, code, subtotal):
    if not code:
        return 0
    coupon = db.get_coupon(code)
    if not coupon or not coupon["active"]:
        return 0
    if coupon["type"] == "percent":
        return subtotal * coupon["value"] / 100
    if coupon["type"] == "fixed":
        return min(coupon["value"], subtotal)
    return 0


def compute_totals(subtotal, discount, country):
    net = subtotal - discount
    shipping = 0 if net >= FREE_SHIPPING_FROM else SHIPPING_FEE
    tax = net * TAX_RATES.get(country, 0)
    return Totals(subtotal, discount, tax, shipping, net + tax + shipping)


def reserve_stock(db, items):
    for item in items:
        db.decrement_stock(item["sku"], item["qty"])


def confirmation_body(customer, order_id, items, total):
    lines = "\n".join(f"{item['sku']} x{item['qty']}" for item in items)
    return (
        f"Hi {customer['first_name']},\n\n"
        f"thanks for your order #{order_id}:\n{lines}\n\n"
        f"Total: {total:.2f} EUR"
    )
```

Why the behaviour is the same:

- **Same order of side effects.** All validation and every `get_product` call still happen before the first `decrement_stock`, then `insert_order`, then the mail. Every error is raised at the same point with the same message.
- **Same arithmetic, same order.** `net + tax + shipping` is evaluated as `((subtotal - discount) + tax) + shipping`, exactly like the old expression, so even the float results are bit-for-bit identical.
- **Same lookups.** The country `if/elif` chain became `TAX_RATES.get(country, 0)`, which has the same default of `0` for unknown countries.
- **Same email text.** `f"{total:.2f}"` equals `'%.2f' % total`. `x{qty}` equals `x%d` as long as `qty` is an `int`. If a float quantity could ever get in, `%d` would truncate it and the f-string would not, so use `{item['qty']:d}` to keep the old strictness.

While I was in there I noticed a few things that I left alone because you asked for no behaviour changes:

1. **Race condition on stock.** The stock check in `price_items` and the decrement in `reserve_stock` aren't atomic. Two concurrent orders can both pass the check. The fix belongs in the database (`UPDATE ... SET stock = stock - ? WHERE sku = ? AND stock >= ?` and check the affected row count) inside one transaction with `insert_order`.
2. **Floats for money.** `0.1 + 0.2`-style errors will show up in `tax` eventually. `decimal.Decimal` with explicit rounding is the usual fix. Now that `compute_totals` is a pure function, that's a small change.
3. **No transaction.** If `insert_order` fails after `reserve_stock`, the stock is gone and there's no order.

A good next step is a couple of tests for `compute_totals` and `coupon_discount`. They're pure functions now, so they need no database at all.

We're turning on `mypy --strict` for the whole repo next sprint. Can you add type hints to this module? It's used by the grading UI and an export script.

```python
import csv
import statistics

GRADE_BOUNDS = [(90, "A"), (80, "B"), (70, "C"), (60, "D")]


def load_scores(path):
    scores = {}
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            scores.setdefault(row["student"], []).append(float(row["score"]))
    return scores


def letter(avg):
    for bound, grade in GRADE_BOUNDS:
        if avg >= bound:
            return grade
    return "F"


def summarize(scores, drop_lowest=False):
    out = {}
    for name, vals in scores.items():
        if drop_lowest and len(vals) > 1:
            vals = sorted(vals)[1:]
        avg = statistics.mean(vals)
        out[name] = {"avg": round(avg, 1), "grade": letter(avg), "n": len(vals)}
    return out


def class_stats(summary):
    avgs = [s["avg"] for s in summary.values()]
    if not avgs:
        return None
    return {
        "mean": statistics.mean(avgs),
        "median": statistics.median(avgs),
        "stdev": statistics.stdev(avgs) if len(avgs) > 1 else 0.0,
    }


def top_students(summary, n=3):
    return sorted(summary, key=lambda name: summary[name]["avg"], reverse=True)[:n]


def write_report(summary, path, sep=","):
    with open(path, "w", newline="") as f:
        w = csv.writer(f, delimiter=sep)
        w.writerow(["student", "avg", "grade", "n"])
        for name in sorted(summary):
            s = summary[name]
            w.writerow([name, s["avg"], s["grade"], s["n"]])
```

