Here's a typed version. Defaults live in exactly one place (the dataclass fields), nested sections merge with their defaults like your `load_config` did, and any unknown key, at any level, is an error:

```python
# config.py
from __future__ import annotations

from collections.abc import Iterable, Mapping
from dataclasses import dataclass, field, fields
from enum import StrEnum
from pathlib import Path
from typing import Any, Self

import torch
import yaml


class Mode(StrEnum):
    TRAIN = "train"
    EVAL = "eval"


class OptimizerName(StrEnum):
    ADAM = "adam"
    ADAMW = "adamw"
    SGD = "sgd"


class Precision(StrEnum):
    FP32 = "fp32"
    FP16 = "fp16"
    BF16 = "bf16"

    @property
    def autocast_dtype(self) -> torch.dtype | None:
        return {Precision.FP16: torch.float16, Precision.BF16: torch.bfloat16}.get(self)


@dataclass(frozen=True)
class OptimizerConfig:
    name: OptimizerName = OptimizerName.ADAM
    lr: float = 1e-3
    weight_decay: float = 0.0
    momentum: float = 0.9  # SGD only

    def __post_init__(self) -> None:
        object.__setattr__(self, "name", OptimizerName(self.name))

    def build(self, params: Iterable[torch.nn.Parameter]) -> torch.optim.Optimizer:
        match self.name:
            case OptimizerName.ADAM:
                return torch.optim.Adam(params, lr=self.lr, weight_decay=self.weight_decay)
            case OptimizerName.ADAMW:
                return torch.optim.AdamW(params, lr=self.lr, weight_decay=self.weight_decay)
            case OptimizerName.SGD:
                return torch.optim.SGD(params, lr=self.lr, momentum=self.momentum,
                                       weight_decay=self.weight_decay)


@dataclass(frozen=True)
class DataConfig:
    train: Path = Path("data/train.jsonl")
    val: Path = Path("data/val.jsonl")
    num_workers: int = 4

    def __post_init__(self) -> None:
        object.__setattr__(self, "train", Path(self.train))
        object.__setattr__(self, "val", Path(self.val))


@dataclass(frozen=True)
class TrainConfig:
    mode: Mode = Mode.TRAIN
    epochs: int = 10
    batch_size: int = 32
    optimizer: OptimizerConfig = field(default_factory=OptimizerConfig)
    scheduler: str | None = None
    precision: Precision = Precision.FP32
    data: DataConfig = field(default_factory=DataConfig)

    def __post_init__(self) -> None:
        object.__setattr__(self, "mode", Mode(self.mode))
        object.__setattr__(self, "precision", Precision(self.precision))

    @classmethod
    def from_yaml(cls, path: str | Path) -> Self:
        raw = yaml.safe_load(Path(path).read_text(encoding="utf-8")) or {}
        return cls.from_dict(raw)

    @classmethod
    def from_dict(cls, raw: Mapping[str, Any]) -> Self:
        _check_keys(cls, raw, "config")
        kw = dict(raw)
        if "optimizer" in kw:
            _check_keys(OptimizerConfig, kw["optimizer"], "optimizer")
            kw["optimizer"] = OptimizerConfig(**kw["optimizer"])
        if "data" in kw:
            _check_keys(DataConfig, kw["data"], "data")
            kw["data"] = DataConfig(**kw["data"])
        return cls(**kw)


def _check_keys(cls: type, raw: Mapping[str, Any], where: str) -> None:
    allowed = {f.name for f in fields(cls)}
    unknown = sorted(set(raw) - allowed)
    if unknown:
        raise ValueError(
            f"unknown key(s) in {where}: {', '.join(unknown)} (allowed: {', '.join(sorted(allowed))})"
        )
```

