I'd split it into three layers. Each one only knows about the layer below it:

```
recipes/
    repo.py      # SQL only: one method per query, no rules, no Flask
    service.py   # the rules: validation, slugs, "can't rate own recipe"; raises exceptions
    web.py       # Flask views: read the request, call the service, map exceptions to HTTP
```

An API blueprint later is just another thin layer over `service.py`.

**`recipes/repo.py`**: the two copies of the list query become one, and creating a recipe is a single transaction:

```python
import sqlite3
from collections.abc import Sequence
from dataclasses import dataclass


@dataclass(frozen=True)
class Ingredient:
    amount: str
    unit: str
    name: str


_LIST_SQL = """
    SELECT r.id, r.slug, r.title, u.name AS author,
           COALESCE(AVG(rt.stars), 0) AS rating, COUNT(rt.stars) AS votes
    FROM recipes r
    JOIN users u ON u.id = r.author_id
    LEFT JOIN ratings rt ON rt.recipe_id = r.id
    {where}
    GROUP BY r.id
    ORDER BY rating DESC
"""


class RecipeRepo:
    def __init__(self, conn: sqlite3.Connection) -> None:
        self.conn = conn

    def search(self, q: str = "") -> list[sqlite3.Row]:
        # only constant SQL fragments are formatted in; the user's text stays a bound parameter
        if q:
            return self.conn.execute(_LIST_SQL.format(where="WHERE r.title LIKE ?"), (f"%{q}%",)).fetchall()
        return self.conn.execute(_LIST_SQL.format(where="")).fetchall()

    def by_slug(self, slug: str) -> sqlite3.Row | None:
        return self.conn.execute("SELECT * FROM recipes WHERE slug = ?", (slug,)).fetchone()

    def ingredients(self, recipe_id: int) -> list[sqlite3.Row]:
        return self.conn.execute(
            "SELECT amount, unit, name FROM ingredients WHERE recipe_id = ? ORDER BY position",
            (recipe_id,),
        ).fetchall()

    def slug_exists(self, slug: str) -> bool:
        return self.conn.execute("SELECT 1 FROM recipes WHERE slug = ?", (slug,)).fetchone() is not None

    def create(self, slug: str, title: str, body: str, author_id: int,
               ingredients: Sequence[Ingredient]) -> int:
        with self.conn:  # commit on success, roll back on any error
            cur = self.conn.execute(
                "INSERT INTO recipes (slug, title, body, author_id) VALUES (?, ?, ?, ?)",
                (slug, title, body, author_id),
            )
            self.conn.executemany(
                "INSERT INTO ingredients (recipe_id, position, amount, unit, name) VALUES (?, ?, ?, ?, ?)",
                [(cur.lastrowid, pos, i.amount, i.unit, i.name) for pos, i in enumerate(ingredients)],
            )
        return cur.lastrowid

    def upsert_rating(self, recipe_id: int, user_id: int, stars: int) -> None:
        with self.conn:
            self.conn.execute(
                "INSERT INTO ratings (recipe_id, user_id, stars) VALUES (?, ?, ?) "
                "ON CONFLICT (recipe_id, user_id) DO UPDATE SET stars = excluded.stars",
                (recipe_id, user_id, stars),
            )
```

**`recipes/service.py`**: plain functions with no Flask imports. Errors are exceptions whose messages are safe to show to users:

```python
import re

from .repo import Ingredient, RecipeRepo


class RecipeError(Exception):
    """Base class; str(e) can be shown to the user."""


class ValidationError(RecipeError):
    pass


class NotFound(RecipeError):
    pass


class OwnRecipe(RecipeError):
    pass


def slugify(title: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-")


def unique_slug(repo: RecipeRepo, title: str) -> str:
    base = slug = slugify(title)
    n = 1
    while repo.slug_exists(slug):
        n += 1
        slug = f"{base}-{n}"
    return slug


def parse_ingredients(text: str) -> list[Ingredient]:
    """'2 cups flour' -> Ingredient('2', 'cups', 'flour'); anything else -> name only."""
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        parts = line.split(None, 2)
        result.append(Ingredient(*parts) if len(parts) == 3 else Ingredient("", "", line.strip()))
    return result


def create_recipe(repo: RecipeRepo, author_id: int, title: str, body: str, ingredients_text: str) -> str:
    title = title.strip()
    if len(title) < 3:
        raise ValidationError("Title too short")
    slug = unique_slug(repo, title)
    repo.create(slug, title, body, author_id, parse_ingredients(ingredients_text))
    return slug


def rate_recipe(repo: RecipeRepo, user_id: int, slug: str, stars: int | None) -> None:
    if stars is None or not 1 <= stars <= 5:
        raise ValidationError("Rating must be between 1 and 5")
    recipe = repo.by_slug(slug)
    if recipe is None:
        raise NotFound(slug)
    if recipe["author_id"] == user_id:
        raise OwnRecipe("You can't rate your own recipe")
    repo.upsert_rating(recipe["id"], user_id, stars)
```

**`recipes/web.py`**: the views shrink to "parse request, call service, respond":

```python
from flask import Blueprint, abort, flash, redirect, render_template, request, session, url_for

from . import service
from .db import get_db
from .repo import RecipeRepo

bp = Blueprint("recipes", __name__)


def repo() -> RecipeRepo:
    return RecipeRepo(get_db())


@bp.route("/")
def index():
    q = request.args.get("q", "").strip()
    return render_template("index.html", recipes=repo().search(q), q=q)


@bp.route("/r/<slug>")
def detail(slug):
    r = repo()
    recipe = r.by_slug(slug)
    if recipe is None:
        abort(404)
    return render_template("detail.html", recipe=recipe, ingredients=r.ingredients(recipe["id"]))


@bp.route("/new", methods=["GET", "POST"])
def new_recipe():
    if "user_id" not in session:
        return redirect(url_for("auth.login"))
    if request.method == "GET":
        return render_template("new.html")
    try:
        slug = service.create_recipe(
            repo(), session["user_id"],
            request.form.get("title", ""), request.form.get("body", ""), request.form.get("ingredients", ""),
        )
    except service.ValidationError as e:
        flash(str(e))
        return render_template("new.html"), 400
    return redirect(url_for("recipes.detail", slug=slug))


@bp.route("/r/<slug>/rate", methods=["POST"])
def rate(slug):
    if "user_id" not in session:
        abort(401)
    try:
        service.rate_recipe(repo(), session["user_id"], slug, request.form.get("stars", type=int))
    except service.ValidationError:
        abort(400)
    except service.NotFound:
        abort(404)
    except service.OwnRecipe as e:
        flash(str(e))
    return redirect(url_for("recipes.detail", slug=slug))
```

`get_db`/`close_db` move unchanged into `recipes/db.py`. The app factory registers the blueprint. Note that endpoint names get the blueprint prefix (`recipes.detail`), so update the `url_for` calls in your templates.

**What stays the same:** every SQL statement, the order of the checks (login, then stars, then recipe exists, then own recipe), the status codes and the flash messages. One improvement comes for free: before, an error halfway through inserting ingredients left the transaction open until teardown. Now `with self.conn` rolls it back explicitly.

