Nesting code for my laser cutter. Rects are (x, y, w, h) tuples and I keep mixing up r[2]/r[3] — last week I cut a whole sheet of plywood with the parts rotated because of it. How do I make this readable without rewriting all the other code that does `x, y, w, h = r`?

```python
def rect_area(r):
    return r[2] * r[3]


def rects_overlap(a, b):
    return not (a[0] + a[2] <= b[0] or b[0] + b[2] <= a[0] or
                a[1] + a[3] <= b[1] or b[1] + b[3] <= a[1])


def rect_center(r):
    return (r[0] + r[2] / 2, r[1] + r[3] / 2)


def inflate(r, margin):
    return (r[0] - margin, r[1] - margin, r[2] + 2 * margin, r[3] + 2 * margin)


def place_parts(parts, sheet_w, sheet_h, gap=2.0):
    # shelf packing, parts = [(name, w, h)]
    placed = []
    x = y = shelf_h = 0.0
    for name, w, h in sorted(parts, key=lambda p: p[2], reverse=True):
        if x + w > sheet_w:
            x = 0.0
            y += shelf_h + gap
            shelf_h = 0.0
        if y + h > sheet_h:
            raise ValueError("part %s does not fit" % name)
        placed.append((name, (x, y, w, h)))
        x += w + gap
        shelf_h = max(shelf_h, h)
    return placed


def to_svg(placed):
    out = []
    for name, r in placed:
        out.append('<rect x="%.2f" y="%.2f" width="%.2f" height="%.2f" id="%s"/>' % (r[0], r[1], r[2], r[3], name))
    return "\n".join(out)
```

Use a `NamedTuple`. It's still a tuple, so `x, y, w, h = r`, `r[2]` and comparisons with plain tuples keep working everywhere, but you get names, and you can attach the geometry as methods:

```python
from typing import NamedTuple


class Rect(NamedTuple):
    x: float
    y: float
    w: float
    h: float

    @property
    def right(self) -> float:
        return self.x + self.w

    @property
    def bottom(self) -> float:
        return self.y + self.h

    @property
    def area(self) -> float:
        return self.w * self.h

    @property
    def center(self) -> tuple[float, float]:
        return (self.x + self.w / 2, self.y + self.h / 2)

    def overlaps(self, other: "Rect") -> bool:
        return not (self.right <= other.x or other.right <= self.x or
                    self.bottom <= other.y or other.bottom <= self.y)

    def inflated(self, margin: float) -> "Rect":
        return Rect(self.x - margin, self.y - margin, self.w + 2 * margin, self.h + 2 * margin)


class Part(NamedTuple):
    name: str
    w: float
    h: float


class Placement(NamedTuple):
    name: str
    rect: Rect


def place_parts(parts: list[Part], sheet_w: float, sheet_h: float, gap: float = 2.0) -> list[Placement]:
    """Shelf packing: tallest parts first, left to right, new shelf when the row is full."""
    placed = []
    x = y = shelf_h = 0.0
    for part in sorted(map(Part._make, parts), key=lambda p: p.h, reverse=True):
        if x + part.w > sheet_w:
            x = 0.0
            y += shelf_h + gap
            shelf_h = 0.0
        if y + part.h > sheet_h:
            raise ValueError(f"part {part.name} does not fit")
        placed.append(Placement(part.name, Rect(x, y, part.w, part.h)))
        x += part.w + gap
        shelf_h = max(shelf_h, part.h)
    return placed


def to_svg(placed: list[Placement]) -> str:
    return "\n".join(
        f'<rect x="{r.x:.2f}" y="{r.y:.2f}" width="{r.w:.2f}" height="{r.h:.2f}" id="{name}"/>'
        for name, r in placed
    )


# old names, so existing callers keep working while you migrate
def rect_area(r): return Rect(*r).area
def rects_overlap(a, b): return Rect(*a).overlaps(Rect(*b))
def rect_center(r): return Rect(*r).center
def inflate(r, margin): return Rect(*r).inflated(margin)
```

Why nothing else breaks:

- A `Rect` *is* a tuple. `x, y, w, h = r` and `r[3]` behave exactly as before, and `Rect(1, 2, 3, 4) == (1, 2, 3, 4)` is `True`.
- `place_parts` still accepts plain `(name, w, h)` tuples (`Part._make` converts them), and it returns pairs that unpack as `name, r`.
- The arithmetic is identical, so the SVG output is byte-for-byte the same.

From here on, write `r.w`/`r.h` in new code. A type checker will also flag a `Rect` passed where a `Part` is expected, which is exactly the kind of mix-up that cost you the plywood.

One thing I noticed while converting, which I did **not** change: a part wider than the sheet is never rejected. At `x = 0` the check `x + w > sheet_w` starts a new shelf, but the part is then placed anyway and sticks out to the right. Add `if part.w > sheet_w: raise ValueError(...)` at the top of the loop if that can happen with your parts list.

When nothing depends on tuple behaviour any more, you can switch to `@dataclass(frozen=True, slots=True)` to lose the index access on purpose. Until then, `NamedTuple` is the low-risk step.

