```python
from typing import Any, Callable, Dict, List, Optional, Tuple, Type, Union

Payload = Dict[str, Any]
Handler = Callable[[Payload], Optional[str]]
Middleware = Callable[[str, Payload], Payload]


class EventBus(object):
    def __init__(self) -> None:
        self._handlers: Dict[str, List[Tuple[int, Handler]]] = {}
        self._middleware: List[Middleware] = []

    def on(self, event: str, priority: int = 0) -> Callable[[Handler], Handler]:
        def deco(fn: Handler) -> Handler:
            self._handlers.setdefault(event, []).append((priority, fn))
            self._handlers[event].sort(key=lambda p: -p[0])
            return fn
        return deco

    def use(self, mw: Middleware) -> "EventBus":
        self._middleware.append(mw)
        return self

    def emit(self, event: str, payload: Optional[Payload] = None) -> List[str]:
        data: Payload = payload or {}
        for mw in self._middleware:
            data = mw(event, data)
        replies: List[str] = []
        for _, fn in self._handlers.get(event, []):
            r = fn(data)
            if r is not None:
                replies.append(r)
        return replies

    def handler_count(self, event: Optional[str] = None) -> int:
        if event is None:
            return sum(len(v) for v in self._handlers.values())
        return len(self._handlers.get(event, []))


def make_bus(cls: Type["EventBus"] = EventBus, middlewares: Optional[List[Middleware]] = None) -> EventBus:
    bus = cls()
    for mw in middlewares or []:
        bus.use(mw)
    return bus


