```python
from collections.abc import Callable
from typing import Any, Self, TypeAlias

Payload: TypeAlias = dict[str, Any]
Handler: TypeAlias = Callable[[Payload], str | None]
Middleware: TypeAlias = Callable[[str, Payload], Payload]


class EventBus:
    def __init__(self) -> None:
        self._handlers: dict[str, list[tuple[int, Handler]]] = {}
        self._middleware: list[Middleware] = []

    def on(self, event: str, priority: int = 0) -> Callable[[Handler], Handler]:
        def deco(fn: Handler) -> Handler:
            self._handlers.setdefault(event, []).append((priority, fn))
            self._handlers[event].sort(key=lambda p: -p[0])
            return fn
        return deco

    def use(self, mw: Middleware) -> Self:
        self._middleware.append(mw)
        return self

    def emit(self, event: str, payload: Payload | None = None) -> list[str]:
        data: Payload = payload or {}
        for mw in self._middleware:
            data = mw(event, data)
        replies: list[str] = []
        for _, fn in self._handlers.get(event, []):
            if (reply := fn(data)) is not None:
                replies.append(reply)
        return replies

    def handler_count(self, event: str | None = None) -> int:
        if event is None:
            return sum(len(v) for v in self._handlers.values())
        return len(self._handlers.get(event, []))


def make_bus(cls: type[EventBus] = EventBus, middlewares: list[Middleware] | None = None) -> EventBus:
    bus = cls()
    for mw in middlewares or []:
        bus.use(mw)
    return bus


def parse_command(text: str) -> tuple[str, list[str]] | None:
    if not text.startswith("!"):
        return None
    name, *args = text[1:].split()
    return name, args
```

If callers pass subclasses to `make_bus` and need the precise return type, use a bound `TypeVar` (`B = TypeVar("B", bound=EventBus)`, `cls: type[B]`, `-> B`). The 3.12 `def make_bus[B: EventBus](...)` syntax isn't available on 3.11. mypy also rejects the `= EventBus` default for a `type[B]` parameter, so you'd need two `@overload`s or a `# type: ignore[assignment]`. Most code doesn't need that, so I kept the simple signature.

What changed:

| Old | New | Since |
|---|---|---|
| `Dict`, `List`, `Tuple`, `Type` | `dict`, `list`, `tuple`, `type` | 3.9 |
| `Optional[X]`, `Union[X, None]` | `X \| None` | 3.10 |
| `typing.Callable` | `collections.abc.Callable` | 3.9 |
| `-> "EventBus"` on `use()` | `-> Self`, so subclasses chain correctly | 3.11 |
| implicit alias `Payload = Dict[...]` | `Payload: TypeAlias = ...` | 3.10 |
| `class EventBus(object)` | `class EventBus` | — |

No runtime behaviour changed. The walrus in `emit` is just a tidier version of the same loop. When you move to 3.12 as the minimum, the aliases can become `type Payload = dict[str, Any]` statements.

