Security review please. This is our scoring service (FastAPI). The QA team uses override_features to test edge cases on staging, but it's the same code in prod.

```python
import base64
import hashlib
import os
import pickle

import redis
from fastapi import FastAPI
from pydantic import BaseModel

from .model import MODEL_VERSION, build_features, model

app = FastAPI()
r = redis.Redis(host=os.environ.get("REDIS_HOST", "cache.internal"), port=6379)


class ScoreRequest(BaseModel):
    user_id: int
    override_features: str | None = None  # base64 pickled dict, used by QA


def cache_key(user_id, model_version):
    return "feat:" + hashlib.md5(f"{user_id}:{model_version}".encode()).hexdigest()


def get_features(user_id, model_version):
    key = cache_key(user_id, model_version)
    blob = r.get(key)
    if blob:
        return pickle.loads(blob)
    feats = build_features(user_id)
    r.set(key, pickle.dumps(feats))
    return feats


@app.post("/score")
def score(req: ScoreRequest):
    feats = get_features(req.user_id, MODEL_VERSION)
    if req.override_features:
        feats.update(pickle.loads(base64.b64decode(req.override_features)))
    return {"score": float(model.predict_proba([feats])[0, 1])}
```

