import os
import subprocess

import yaml


def load_pipeline(repo_dir):
    with open(os.path.join(repo_dir, ".minici.yml")) as f:
        return yaml.load(f, Loader=yaml.Loader)


def should_run(step, env):
    cond = step.get("if", "True")
    return eval(cond, {}, env)


def run_pipeline(repo_dir, secrets):
    pipeline = load_pipeline(repo_dir)
    env = {**os.environ, **pipeline.get("env", {}), **secrets}
    print("running with env:", env)
    for step in pipeline["steps"]:
        if not should_run(step, env):
            print("skip", step["name"])
            continue
