        _token = body["access_token"]
        _token_expiry = time.time() + body["expires_in"]
    return _token


class RateLimiter:
    """Token bucket: `rate` requests per second, bursts up to `burst`."""

    def __init__(self, rate, burst):
        self.rate = rate
        self.burst = burst

    def allow(self, key):
        now = time.time()
        bucket = _buckets.get(key)
        if bucket is None:
            bucket = _buckets[key] = {"tokens": self.burst, "ts": now}
        elapsed = now - bucket["ts"]
        bucket["tokens"] = min(self.burst, bucket["tokens"] + elapsed * self.rate)
        bucket["ts"] = now
        if bucket["tokens"] >= 1:
            bucket["tokens"] -= 1
            return True
        return False


class Stats:
    counts = {}

    def incr(self, name):
        with _lock:
            self.counts[name] = self.counts.get(name, 0) + 1

    def snapshot(self):
        return self.counts


def call_partner_api(path, payload, limiter=RateLimiter(5, 10)):
    if not limiter.allow("partner"):
        raise RuntimeError("rate limited")
    for attempt in range(3):
        try:
            r = requests.post(
                BASE_URL + path,
                json=payload,
                headers={"Authorization": f"Bearer {get_token()}"},
                timeout=10,
            )
            if r.status_code == 401:
                global _token
                _token = None
                continue
            r.raise_for_status()
            Stats().incr(path)
            return r.json()
        except requests.ConnectionError:
            time.sleep(2 ** attempt)
    raise RuntimeError("partner API failed")
