Our FastAPI currency service slowly eats memory (restarted by k8s every ~2 days) and a customer reported seeing someone else's currency pairs in the "skipped" list of their response. A new RateService is created per request with its own httpx client. Here's the class, can you review?

```python
from datetime import date
from functools import lru_cache


class RateNotFound(Exception):
    pass


class RateService:
    def __init__(self, client):
        self.client = client

    @lru_cache(maxsize=None)
    def rate(self, base, quote, day):
        r = self.client.fetch_rate(base, quote, day.isoformat())
        if r is None:
            raise RateNotFound(f"{base}/{quote} on {day}")
        return r

    def convert(self, amount, base, quote, day=date.today()):
        return amount * self.rate(base, quote, day)

    def convert_many(self, items, quote, skipped=[]):
        total = 0.0
        for amount, base, day in items:
            if base == quote:
                total += amount
                continue
            try:
                total += self.convert(amount, base, quote, day)
            except RateNotFound:
                skipped.append((base, day))
        return total, skipped
