```python
from datetime import datetime, timedelta

import pytz

BERLIN = pytz.timezone("Europe/Berlin")


def period_start(now=None):
    now = now or datetime.now()
    return datetime(now.year, now.month, 1, tzinfo=BERLIN)


def next_renewal(last_renewal):
    return last_renewal + timedelta(days=30)


def is_expired(sub):
    return sub.expires_at < datetime.utcnow()


def to_local(dt):
    return dt.replace(tzinfo=BERLIN)


def invoice_date_label(dt):
    return to_local(dt).strftime("%d.%m.%Y")
