```python
import os


class Field:
    def __init__(self, cast, default=None):
        self.cast = cast
        self.default = default

    def __set_name__(self, owner, name):
        self.name = name
        self.env = f"{owner.prefix}_{name}".upper()

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        raw = os.environ.get(self.env)
        return self.default if raw is None else self.cast(raw)


class Settings:
    prefix = "app"
    registry = {}

    def __init_subclass__(cls, prefix=None, **kwargs):
        super().__init_subclass__(**kwargs)
        if prefix is not None:
            cls.prefix = prefix
        Settings.registry[cls.__name__.lower()] = cls


class DB(Settings, prefix="db"):
    host = Field(str, "localhost")
    port = Field(int, 5432)


class Cache(Settings, prefix="cache"):
    url = Field(str, "redis://localhost:6379/0")
    enabled = Field(bool, True)
